"""RESULTS.md and web/public/data/dashboard.json from reports/*.json. Deterministic; do not edit the outputs."""

from __future__ import annotations

import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
REPORTS = ROOT / "reports"


def load(name: str) -> dict | None:
    p = REPORTS / f"{name}.json"
    return json.loads(p.read_text()) if p.exists() else None


def tests() -> dict:
    out = subprocess.run(
        [sys.executable, "-m", "pytest", "--collect-only", "-q"], cwd=ROOT, capture_output=True, text=True
    ).stdout
    m = re.search(r"(\d+) tests? collected", out)
    web = sum(len(re.findall(r"^\s*it\(", p.read_text(), re.M)) for p in (ROOT / "web" / "test").glob("*.test.tsx"))
    return {"python": int(m.group(1)) if m else 0, "web": web}


KEEP = (
    "drawings",
    "media",
    "layouts",
    "regions",
    "fields",
    "dimensions",
    "parts_list",
    "notes",
    "revisions",
    "feasibility",
    "onboarding",
    "review",
)


def split(r: dict | None) -> dict | None:
    return {k: r[k] for k in KEEP} if r else None


def pct(x: float, d: int = 1) -> str:
    return f"{x * 100:.{d}f}%"


def main() -> None:
    dev, held, show, loo = load("dev"), load("heldout"), load("showcase"), load("regions_dev_loo")
    from dia.settings import load as settings

    s = settings()
    data = {
        "tests": tests(),
        "dev": split(dev),
        "heldout": split(held),
        "routing": {
            "threshold": s.routing.min_confidence,
            "max_error": s.routing.max_auto_error,
            "curve": dev["routing_curve"],
        },
        "regions_loo": loo or {},
        "showcase": show,
    }
    web = ROOT / "web" / "public" / "data"
    web.mkdir(parents=True, exist_ok=True)
    (web / "dashboard.json").write_text(json.dumps(data, indent=1, sort_keys=True, ensure_ascii=False) + "\n")
    (ROOT / "RESULTS.md").write_text(render(data))
    print("RESULTS.md, web/public/data/dashboard.json")


def render(d: dict) -> str:
    dev, held = d["dev"], d["heldout"]
    cols = [("Development", dev)] + ([("Held-out (run once)", held)] if held else [])
    rows = [
        (
            "Drawings (vector / scan)",
            lambda r: f"{r['drawings']} ({r['media'].get('vector', 0)} / {r['media'].get('scan', 0)})",
        ),
        ("Customer layouts", lambda r: ", ".join(r["layouts"])),
        ("Title-block fields right", lambda r: pct(r["fields"]["all"])),
        ("... CAD PDFs", lambda r: pct(r["fields"].get("medium:vector", 0))),
        ("... scans", lambda r: pct(r["fields"].get("medium:scan", 0))),
        ("Dimensions read exactly (recall)", lambda r: pct(r["dimensions"]["all"]["recall_exact"])),
        ("... CAD PDFs", lambda r: pct(r["dimensions"].get("vector", {}).get("recall_exact", 0))),
        ("... scans", lambda r: pct(r["dimensions"].get("scan", {}).get("recall_exact", 0))),
        ("Read dimensions that are right (precision)", lambda r: pct(r["dimensions"]["all"]["precision_exact"])),
        ("Nominal value right", lambda r: pct(r["dimensions"]["all"]["recall_nominal"])),
        ("Limits of size right", lambda r: pct(r["dimensions"]["all"]["limits_right"])),
        ("Parts-list cells right", lambda r: f"{pct(r['parts_list']['cell_accuracy'])} of {r['parts_list']['cells']}"),
        (
            "Note requirements: recall / precision",
            lambda r: f"{pct(r['notes']['recall'])} / {pct(r['notes']['precision'])}",
        ),
        (
            "Revision changes: recall / precision",
            lambda r: (
                f"{pct(r['revisions']['recall'])} / "
                f"{pct(r['revisions']['precision'])} "
                f"({r['revisions']['changes']} changes)"
            ),
        ),
        ("Make-or-partner decision as from the drawing", lambda r: pct(r["feasibility"]["route_agreement"])),
        ("Fields sent straight to the ERP", lambda r: pct(r["review"]["auto_accepted_share"])),
        (
            "Wrong values among those",
            lambda r: f"{r['review']['wrong_among_auto_accepted']} ({pct(r['review']['error_among_auto_accepted'])})",
        ),
        (
            "Minutes per drawing, manual (assumed) / with the desk",
            lambda r: (
                f"{r['review']['minutes_per_drawing_manual_assumed']:g} / "
                f"{r['review']['minutes_per_drawing_with_desk']:g}"
            ),
        ),
    ]
    L = [
        "# Results",
        "",
        f"Generated by `scripts/report.py` from `reports/*.json`. Tests: {d['tests']['python']} Python, "
        f"{d['tests']['web']} web.",
        "",
        "| Measure | " + " | ".join(c for c, _ in cols) + " |",
        "|---|" + "---:|" * len(cols),
    ]
    for name, f in rows:
        L.append(f"| {name} | " + " | ".join(f(r) for _, r in cols) + " |")
    L += [
        "",
        "## Finding the regions of a sheet",
        "",
        "Mean intersection over union with the true region, per sheet.",
        "",
        "| Region | " + " | ".join(f"{c}: U-Net | {c}: template" for c, _ in cols) + " |",
        "|---|" + "---:|---:|" * len(cols),
    ]
    for cls in ("title_block", "parts_list", "revision_table", "notes", "view"):
        cells = []
        for _, r in cols:
            for m in ("detector", "template"):
                v = r["regions"][m].get(cls)
                cells.append(pct(v["mean_iou"]) if v else "–")
        L.append(f"| {cls} | " + " | ".join(cells) + " |")
    if d["regions_loo"]:
        L += [
            "",
            "Leave-one-development-layout-out (U-Net trained on the other four):",
            "",
            "| Left out | " + " | ".join(next(iter(d["regions_loo"].values())).keys()) + " |",
            "|---|" + "---:|" * len(next(iter(d["regions_loo"].values()))),
        ]
        for lay, v in d["regions_loo"].items():
            L.append(f"| {lay} | " + " | ".join(pct(x) for x in v.values()) + " |")
    L += [
        "",
        "## A new customer's title block",
        "",
        "| Example drawings | " + " | ".join(c for c, _ in cols) + " |",
        "|---:|" + "---:|" * len(cols),
    ]
    for k in ("0", "1", "3"):
        L.append(f"| {k} | " + " | ".join(pct(r["onboarding"][k]["field_accuracy"]) for _, r in cols) + " |")
    L += [
        "",
        f"Routing threshold {d['routing']['threshold']} (chosen on development drawings for at most "
        f"{pct(d['routing']['max_error'])} wrong among accepted fields).",
        "",
    ]
    return "\n".join(L)


if __name__ == "__main__":
    sys.path.insert(0, str(ROOT / "src"))
    main()
